"""Adds every asset generated by game_src/batch*.sh to game_src/manifest.json: the gen3d call
(image / model / outfit image + model), prompt, seed, faces, and the job id and server folder
from the job's JSON next to the output. Hand-written entries (with notes) are kept.

python3 tools/docs/manifest.py
"""
import json
import re
import shlex
from pathlib import Path

root = Path(__file__).resolve().parents[2]
src = root / "game_src"
man_path = src / "manifest.json"
man = json.loads(man_path.read_text())
assets = man["assets"]


def relative(p):
    """A job's folder on the GPU box -> `<date>/<job>` (tools/docs/scrub_paths.py)."""
    if isinstance(p, str) and p.startswith("/"):
        return "/".join(p.rstrip("/").split("/")[-2:])
    return p


def expand(text, env):
    return re.sub(r"\$(\w+)", lambda m: env.get(m.group(1), m.group(0)), text)


added = 0
for batch in sorted(src.glob("batch*.sh"), key=lambda p: int(re.sub(r"\D", "", p.stem) or 0)):
    env = {}
    for line in batch.read_text().splitlines():
        m = re.match(r'^(\w+)="(.*)"$', line)
        if m:
            env[m.group(1)] = expand(m.group(2), env)
            continue
        if not re.match(r"^(img|mdl|out) ", line):
            continue
        try:
            parts = shlex.split(line)
        except ValueError:
            continue
        kind, name = parts[0], parts[1]
        entry = {"batch": batch.name, "steps": []}
        if kind == "img":
            entry["steps"].append({"gen3d": "image", "prompt": expand(parts[2], env),
                                   "negative": expand(parts[3], env) if len(parts) > 3 else "",
                                   "seed": int(parts[4]) if len(parts) > 4 else None})
            key = f"raw/{name}.png"
        elif kind == "mdl":
            step = {"gen3d": "model", "prompt": expand(parts[2], env), "negative": env.get("N3", ""),
                    "seed": int(parts[3]), "faces": int(parts[4]), "texture": 1024}
            job = src / "raw" / f"{name}.json"
            if job.exists():
                try:
                    j = json.loads(job.read_text())
                    step["job"] = j.get("job")
                    step["server_dir"] = relative(j.get("server_dir"))
                except json.JSONDecodeError:
                    step["failed"] = job.read_text().strip()[-200:]
            entry["steps"].append(step)
            key = f"raw/{name}.glb"
        else:  # out: image with ControlNet depth of the base body, then image-to-3D
            seed, prompt = int(parts[2]), expand(parts[3], env)
            entry["steps"].append({"gen3d": "image", "prompt": f"{prompt}, {env.get('SC', '')}",
                                   "control": "spike/control/depth.png", "control_scale": 0.6,
                                   "control_end": 0.75, "seed": seed})
            step = {"gen3d": "model", "image": f"raw/{name}.png", "seed": 7, "faces": 60000, "texture": 2048}
            job = src / "raw" / f"{name}.json"
            if job.exists():
                try:
                    j = json.loads(job.read_text())
                    step["job"] = j.get("job")
                    step["server_dir"] = relative(j.get("server_dir"))
                except json.JSONDecodeError:
                    pass
            entry["steps"].append(step)
            entry["post"] = "tools/pipeline/outfit.py (baked onto the base body)"
            key = f"raw/{name}.glb"
        if key in assets and "note" in json.dumps(assets[key]):
            continue
        if assets.get(key) != entry:
            assets[key] = entry
            added += 1

man_path.write_text(json.dumps(man, indent=2, ensure_ascii=False) + "\n")
print(f"{added} entries added or updated, {len(assets)} in total")
